import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from normalQuantile ----
/** mulberry32, seeded so the sample is byte-identical on every reload. */
function createRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function createSample(count: number, seed: number): number[] {
  const random = createRandom(seed);
  const values: number[] = [];
  while (values.length < count) {
    const u = random() || Number.EPSILON; // Box-Muller diverges at exactly zero
    const normal = Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * random());
    values.push(Math.round(Math.exp(3.4 + 0.55 * normal) * 10) / 10);
  }
  return values;
}

/** Lognormal, so the sample is visibly right-skewed and the plot bends away from its own fit. */
const componentStrength: number[] = createSample(320, 20260813);

const MARGIN = { top: 22, right: 20, bottom: 44, left: 52 };

const LOW_A = [
  -7.784894002430293e-3, -3.223964580411365e-1, -2.400758277161838, -2.549732539343734,
  4.374664141464968, 2.938163982698783
];
const LOW_B = [7.784695709041462e-3, 3.224671290700398e-1, 2.445134137142996, 3.754408661907416];
const MID_A = [
  -3.969683028665376e1, 2.209460984245205e2, -2.759285104469687e2, 1.38357751867269e2,
  -3.066479806614716e1, 2.506628277459239
];
const MID_B = [
  -5.447609879822406e1, 1.615858368580409e2, -1.556989798598866e2, 6.680131188771972e1,
  -1.328068155288572e1
];

/** Acklam's rational approximation of the standard normal inverse CDF; the exact form has none. */
function probit(p: number): number {
  if (p < 0.02425) {
    const q = Math.sqrt(-2 * Math.log(p));
    return (
      (((((LOW_A[0] * q + LOW_A[1]) * q + LOW_A[2]) * q + LOW_A[3]) * q + LOW_A[4]) * q + LOW_A[5]) /
      ((((LOW_B[0] * q + LOW_B[1]) * q + LOW_B[2]) * q + LOW_B[3]) * q + 1)
    );
  }
  if (p > 1 - 0.02425) return -probit(1 - p);
  const q = p - 0.5;
  const r = q * q;
  return (
    ((((((MID_A[0] * r + MID_A[1]) * r + MID_A[2]) * r + MID_A[3]) * r + MID_A[4]) * r + MID_A[5]) *
      q) /
    (((((MID_B[0] * r + MID_B[1]) * r + MID_B[2]) * r + MID_B[3]) * r + MID_B[4]) * r + 1)
  );
}

/** The raw sample, in any order; the chart sorts it. */
export type Data = number[];

export default function NormalQuantilePlot({
  data = componentStrength,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.66);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  // Rank each sorted observation against the normal quantile it would sit at if the sample
  // were normal. `a` is the plotting-position offset; 5/8 is the small-sample correction.
  const points = useMemo(() => {
    const sorted = [...data].sort(d3.ascending);
    const count = sorted.length;
    const a = count <= 10 ? 5 / 8 : 0.5;
    return sorted.map((value, i) => ({ z: probit((i + a) / (count + 1 - 2 * a)), value }));
  }, [data]);

  const fit = useMemo(() => {
    const meanZ = d3.mean(points, (p) => p.z) ?? 0;
    const meanValue = d3.mean(points, (p) => p.value) ?? 0;
    const covariance = d3.sum(points, (p) => (p.z - meanZ) * (p.value - meanValue));
    const variance = d3.sum(points, (p) => (p.z - meanZ) * (p.z - meanZ));
    const slope = variance === 0 ? 0 : covariance / variance;
    return { slope, intercept: meanValue - slope * meanZ };
  }, [points]);

  const x = useMemo(
    () => d3.scaleLinear().domain([-3, 3]).nice().range([0, innerWidth]),
    [innerWidth]
  );

  const fitLine = useMemo(() => {
    const [z0, z1] = x.domain();
    return { z0, z1, v0: fit.intercept + fit.slope * z0, v1: fit.intercept + fit.slope * z1 };
  }, [x, fit]);

  // Domain spans the fit endpoints and the data, so the skewed tail stays inside the viewport.
  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([
          Math.min(d3.min(points, (p) => p.value) ?? 0, fitLine.v0),
          Math.max(d3.max(points, (p) => p.value) ?? 0, fitLine.v1)
        ])
        .nice()
        .range([innerHeight, 0]),
    [points, fitLine, innerHeight]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x
        .ticks(Math.max(3, Math.round(innerWidth / 90)))
        .map((v) => ({ value: String(v), offset: x(v) })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () =>
      y
        .ticks(Math.max(3, Math.round(innerHeight / 50)))
        .map((v) => ({ value: String(v), offset: y(v) })),
    [y, innerHeight]
  );

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Normal quantile plot of component strength against theoretical normal quantiles, with a least-squares reference line">
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />

        <g className="axis">
          {xTicks.map(({ value, offset }) => (
            <line key={value} className="grid" x1={offset} x2={offset} y1={0} y2={innerHeight} />
          ))}
        </g>

        <g className="axis">
          <text x={innerWidth} y={innerHeight + MARGIN.bottom - 6} textAnchor="end">
            Theoretical normal quantile z →
          </text>
          <text x={-MARGIN.left} y={-8} textAnchor="start">
            ↑ Strength (MPa)
          </text>
        </g>

        <line
          x1={x(fitLine.z0)}
          x2={x(fitLine.z1)}
          y1={y(fitLine.v0)}
          y2={y(fitLine.v1)}
          stroke="var(--muted)"
          strokeWidth={1.5}
        />

        <g fill="none" stroke="var(--accent)" strokeWidth={1.25}>
          {points.map((p, i) => (
            <circle key={i} cx={x(p.z)} cy={y(p.value)} r={2.5} />
          ))}
        </g>
      </g>
    </svg>
  );
}
